import React, { useState, useEffect } from 'react';
import './CSS/AdminDashboard.css';
import { Link } from 'react-router-dom';
import axios from 'axios';

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('overview');
  const [selectedUser, setSelectedUser] = useState(null);
  const [detailModalItem, setDetailModalItem] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [stats, setStats] = useState({
    totalBuyers: 0,
    totalSellers: 0,
    totalAmount: 0
  });

  const [auditLogs, setAuditLogs] = useState([]);
  const [users, setUsers] = useState([]);

  const [settingsTab, setSettingsTab] = useState('general');

  const [generalSettings, setGeneralSettings] = useState({
    siteName: 'HEXCART',
    supportEmail: 'support@hexcart.com',
    currency: 'USD ($)',
    maintenanceMode: false,
  });

  const [securitySettings, setSecuritySettings] = useState({
    twoFactorAuth: true,
    sessionTimeout: '30',
    ipWhitelisting: false,
  });

  const [notificationSettings, setNotificationSettings] = useState({
    emailAlerts: true,
    userRegistrationAlerts: true,
    sellerPayoutAlerts: true,
    systemLogsAlerts: false,
  });

  // 🔐 NEW: Change Password State
  const [passwordData, setPasswordData] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });

  useEffect(() => {
    const fetchAdminData = async () => {
      try {
        const statsRes = await axios.get('http://localhost:4000/api/admin/stats');
        setStats(statsRes.data);

        const logsRes = await axios.get('http://localhost:4000/api/admin/audit-logs');
        setAuditLogs(logsRes.data);

        const usersRes = await axios.get('http://localhost:4000/api/admin/users');

        if (usersRes.data && usersRes.data.length > 0) {
          const dynamicUsers = usersRes.data.map(user => {
            const matchedLogs = logsRes.data
              .filter(log => log.entityName === user.name || log.entityName === user.storeName)
              .map(log => ({
                date: new Date(log.timestamp).toLocaleString(),
                action: log.actionDetail
              }));

            return {
              ...user,
              activities: matchedLogs.length > 0
                ? matchedLogs
                : [{ date: 'N/A', action: 'No recent activity recorded' }]
            };
          });

          setUsers(dynamicUsers);
        }

      } catch (err) {
        console.error("Error fetching backend admin data:", err);
      }
    };

    fetchAdminData();
    const interval = setInterval(fetchAdminData, 5000);
    return () => clearInterval(interval);
  }, []);

  const toggleStatus = (id) => {
    setUsers(users.map(u =>
      u.id === id
        ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' }
        : u
    ));
  };

  const toggleUserActivity = (user) => {
    if (selectedUser && selectedUser.id === user.id) {
      setSelectedUser(null);
    } else {
      setSelectedUser(user);
    }
  };

  const handleSaveSettings = (e) => {
    e.preventDefault();
    alert('Settings updated successfully!');
  };

  // 🔐 NEW: Change Password Handler
  const handleChangePassword = async () => {
    const { currentPassword, newPassword, confirmPassword } = passwordData;

    if (!currentPassword || !newPassword || !confirmPassword) {
      alert("Please fill all fields");
      return;
    }

    if (newPassword !== confirmPassword) {
      alert("New passwords do not match");
      return;
    }

    try {
      const res = await axios.post(
        "http://localhost:4000/api/admin/change-password",
        {
          currentPassword,
          newPassword
        }
      );

      alert(res.data.message || "Password updated successfully");

      setPasswordData({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      });

    } catch (err) {
      console.error(err);
      alert(err.response?.data?.message || "Error updating password");
    }
  };

  const filteredUsers = users.filter(user => {
    const term = searchTerm.toLowerCase();
    return (
      user.name?.toLowerCase().includes(term) ||
      user.email?.toLowerCase().includes(term) ||
      user.storeName?.toLowerCase().includes(term)
    );
  });

  const renderContent = () => {
    switch (activeTab) {

      /* ================= OVERVIEW ================= */
      case 'overview':
        return (
          <div className="tab-panel fade-in">
            <h2>Dashboard Overview</h2>
          </div>
        );

      /* ================= SETTINGS ================= */
      case 'settings':
        return (
          <div className="tab-panel fade-in">

            <h2>Platform Settings</h2>

            <div className="settings-nav-tabs">
              <button onClick={() => setSettingsTab('general')}>General</button>
              <button onClick={() => setSettingsTab('security')}>Security</button>
              <button onClick={() => setSettingsTab('notifications')}>Notifications</button>
            </div>

            <form onSubmit={handleSaveSettings}>

              {/* GENERAL */}
              {settingsTab === 'general' && (
                <div>
                  <input
                    value={generalSettings.siteName}
                    onChange={(e) =>
                      setGeneralSettings({ ...generalSettings, siteName: e.target.value })
                    }
                  />
                </div>
              )}

              {/* SECURITY */}
              {settingsTab === 'security' && (
                <div>

                  <label>
                    <input
                      type="checkbox"
                      checked={securitySettings.twoFactorAuth}
                      onChange={(e) =>
                        setSecuritySettings({
                          ...securitySettings,
                          twoFactorAuth: e.target.checked
                        })
                      }
                    />
                    2FA Enable
                  </label>

                  <input
                    type="number"
                    value={securitySettings.sessionTimeout}
                    onChange={(e) =>
                      setSecuritySettings({
                        ...securitySettings,
                        sessionTimeout: e.target.value
                      })
                    }
                  />

                  <hr />

                  {/* 🔐 CHANGE PASSWORD FEATURE */}
                  <h3>Change Password</h3>

                  <input
                    type="password"
                    placeholder="Current Password"
                    value={passwordData.currentPassword}
                    onChange={(e) =>
                      setPasswordData({
                        ...passwordData,
                        currentPassword: e.target.value
                      })
                    }
                  />

                  <input
                    type="password"
                    placeholder="New Password"
                    value={passwordData.newPassword}
                    onChange={(e) =>
                      setPasswordData({
                        ...passwordData,
                        newPassword: e.target.value
                      })
                    }
                  />

                  <input
                    type="password"
                    placeholder="Confirm Password"
                    value={passwordData.confirmPassword}
                    onChange={(e) =>
                      setPasswordData({
                        ...passwordData,
                        confirmPassword: e.target.value
                      })
                    }
                  />

                  <button type="button" onClick={handleChangePassword}>
                    Update Password
                  </button>

                </div>
              )}

              {/* NOTIFICATIONS */}
              {settingsTab === 'notifications' && (
                <div>
                  <label>
                    <input
                      type="checkbox"
                      checked={notificationSettings.emailAlerts}
                      onChange={(e) =>
                        setNotificationSettings({
                          ...notificationSettings,
                          emailAlerts: e.target.checked
                        })
                      }
                    />
                    Email Alerts
                  </label>
                </div>
              )}

              <button type="submit">Save Settings</button>
            </form>
          </div>
        );

      default:
        return <div>Page</div>;
    }
  };

  return (
    <div className="admin-wrapper">

      <aside className="admin-sidebar">
        <button onClick={() => setActiveTab('overview')}>Dashboard</button>
        <button onClick={() => setActiveTab('settings')}>Settings</button>
      </aside>

      <div className="admin-main">

        <header>
          <input
            placeholder="Search..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />

          <Link to="/">Home</Link>
        </header>

        <main>
          {renderContent()}
        </main>

      </div>
    </div>
  );
};

export default AdminDashboard;
